1	'use client'
2	
3	import { Html, OrbitControls } from '@react-three/drei'
4	import { useFrame, useThree, type ThreeEvent } from '@react-three/fiber'
5	import { useEffect, useMemo, useRef, useState, type ElementRef, type ReactNode } from 'react'
6	import {
7	  AdditiveBlending,
8	  BoxGeometry,
9	  BufferAttribute,
10	  BufferGeometry,
11	  CircleGeometry,
12	  Color,
13	  CylinderGeometry,
14	  DoubleSide,
15	  InstancedBufferAttribute,
16	  Matrix4,
17	  ShaderMaterial,
18	  UniformsLib,
19	  UniformsUtils,
20	  Vector3,
21	  type InstancedMesh,
22	  type LineBasicMaterial,
23	  type Mesh,
24	} from 'three'
25	import type { Finding, SafetyDepartment, SafetyTarget } from '@/deck/contract'
26	import { easeInOutCubic } from '@/deck/easing'
27	import { layoutCity, type CityBlock, type CityLayout } from '@/deck/layout-city'
28	import { usePrefersReducedMotion } from '@/deck/motion'
29	import { languageColor, SEVERITY_COLOR } from '@/deck/palette'
30	import { createGlowMaterial } from '@/components/three/glow'
31	import { Stage } from '@/components/three/Stage'
32	import styles from './safety-stage.module.css'
33	
34	/** Beacon height per severity, in scene units: a critical finding stands over the whole city. */
35	const BEACON_HEIGHT: Record<string, number> = {
36	  critical: 36,
37	  high: 27,
38	  medium: 19,
39	  low: 13,
40	  info: 9,
41	}
42	
43	/** Beacon radius per severity. */
44	const BEACON_RADIUS: Record<string, number> = {
45	  critical: 0.66,
46	  high: 0.54,
47	  medium: 0.45,
48	  low: 0.38,
49	  info: 0.32,
50	}
51	
52	/** Beacon and halo brightness per severity. */
53	const BEACON_GAIN: Record<string, number> = {
54	  critical: 1.55,
55	  high: 1.15,
56	  medium: 0.92,
57	  low: 0.74,
58	  info: 0.6,
59	}
60	
61	/** Marker-head size per severity, in the point material's units. */
62	const MARKER_SIZE: Record<string, number> = {
63	  critical: 8.5,
64	  high: 7,
65	  medium: 6,
66	  low: 5.2,
67	  info: 4.6,
68	}
69	
70	/** Radius of the halo standing at a beacon's foot, in scene units. */
71	const HALO_RADIUS = 1.9
72	
73	/** Window cell size on a building wall, in scene units: pane width, then floor height. */
74	const WINDOW_CELL: [number, number] = [0.8, 1.05]
75	
76	/** Seconds the opening fly-over takes. */
77	const FLYOVER_SECONDS = 3
78	
79	/** Seconds a flight to or from a selected finding takes. */
80	const FOCUS_SECONDS = 1.2
81	
82	/** Seconds one scan sweep takes to cross the city. */
83	const SWEEP_SECONDS = 5.5
84	
85	/** Seconds between one scan sweep and the next. */
86	const SWEEP_GAP_SECONDS = 1.6
87	
88	/**
89	 * How far back the camera stands from a city of this size, in scene units.
90	 *
91	 * A wide repository is framed by its footprint; a narrow one by its tallest
92	 * beacon, which stands well above even the tallest file. Taking the larger of
93	 * the two keeps the critical shafts inside the frame whatever the target's
94	 * proportions, so height keeps reading as severity.
95	 * @param extent - Half-extent of the city footprint.
96	 * @param reach - Height of the tallest beacon above the ground.
97	 * @returns The resting camera distance.
98	 */
99	function cityDistance(extent: number, reach: number): number {
100	  return Math.max(extent * 3.15, reach * 2.7)
101	}
102	
103	/**
104	 * The establishing view of one city: far enough back that the tallest beacon
105	 * stays inside the frame, looking at the towers rather than at the ground.
106	 * @param extent - Half-extent of the city footprint.
107	 * @param reach - Height of the tallest beacon above the ground.
108	 * @returns The camera position and the point it looks at.
109	 */
110	function cityView(extent: number, reach: number): { position: Vector3; target: Vector3 } {
111	  return {
112	    position: new Vector3(0.58, 0.8, 1.28).normalize().multiplyScalar(cityDistance(extent, reach)),
113	    target: new Vector3(0, 15, 0),
114	  }
115	}
116	
117	/**
118	 * Where the opening fly-over starts: high over the far edge of the city,
119	 * looking back across it.
120	 * @param extent - Half-extent of the city footprint.
121	 * @param reach - Height of the tallest beacon above the ground.
122	 * @returns The camera position and the point it looks at.
123	 */
124	function flyoverStart(extent: number, reach: number): { position: Vector3; target: Vector3 } {
125	  return {
126	    position: new Vector3(-0.5, 1.52, -1).normalize().multiplyScalar(cityDistance(extent, reach) * 1.27),
127	    target: new Vector3(0, 4, 0),
128	  }
129	}
130	
131	/**
132	 * Where the callout hangs on one beacon: part-way up the shaft, so it stays in
133	 * frame while the building below it stays readable.
134	 * @param entry - The placed finding.
135	 * @returns The anchor point.
136	 */
137	function calloutAnchor(entry: PlacedFinding): Vector3 {
138	  return entry.base.clone().setY(entry.base.y + (entry.height * 0.34))
139	}
140	
141	/**
142	 * The framing of one finding: the camera stands off its building far enough to
143	 * hold the building, its halo and the callout on its shaft.
144	 * @param entry - The finding to frame.
145	 * @returns The camera position and the point it looks at.
146	 */
147	function focusView(entry: PlacedFinding): { position: Vector3; target: Vector3 } {
148	  const target = new Vector3(entry.base.x, (entry.base.y * 0.82) + (entry.height * 0.16), entry.base.z)
149	  const distance = 23 + (entry.height * 0.62) + (entry.block.height * 0.6)
150	  return {
151	    position: target.clone().add(new Vector3(0.58, 0.55, 1.05).normalize().multiplyScalar(distance)),
152	    target,
153	  }
154	}
155	
156	const SCRATCH = new Matrix4()
157	const SCRATCH_SCALE = new Vector3()
158	const SCRATCH_POSITION = new Vector3()
159	
160	/** One finding, resolved to a beacon standing on its file. */
161	interface PlacedFinding {
162	  finding: Finding
163	  block: CityBlock
164	  /** Foot of the beacon, on the file's roof. */
165	  base: Vector3
166	  /** Top of the beacon: the marker head and the callout anchor. */
167	  head: Vector3
168	  height: number
169	  radius: number
170	  /** Brightness multiplier the severity earns. */
171	  gain: number
172	}
173	
174	/**
175	 * Resolve every finding onto its file's block, spreading repeats on one file
176	 * around the roof so two beacons never stand in the same place.
177	 * @param findings - The review's findings.
178	 * @param city - The laid-out city.
179	 * @returns Only the findings whose file the target actually reports.
180	 */
181	function placeFindings(findings: readonly Finding[], city: CityLayout): PlacedFinding[] {
182	  const perFile = new Map<string, number>()
183	  const placed: PlacedFinding[] = []
184	  for (const finding of findings) {
185	    const block = city.byPath.get(finding.file)
186	    if (block === undefined) continue
187	    const ordinal = perFile.get(finding.file) ?? 0
188	    perFile.set(finding.file, ordinal + 1)
189	    // Repeats stand on a golden-angle ring, which spreads any count evenly.
190	    const angle = ordinal * 2.399_96
191	    const spread = ordinal === 0 ? 0 : 0.78
192	    const height = (BEACON_HEIGHT[finding.severity] ?? 12) * (1 - (ordinal * 0.06))
193	    const base = new Vector3(
194	      block.x + (Math.cos(angle) * spread),
195	      block.height,
196	      block.z + (Math.sin(angle) * spread),
197	    )
198	    placed.push({
199	      finding,
200	      block,
201	      base,
202	      head: base.clone().setY(block.height + height),
203	      height,
204	      radius: BEACON_RADIUS[finding.severity] ?? 0.4,
205	      gain: BEACON_GAIN[finding.severity] ?? 0.7,
206	    })
207	  }
208	  return placed
209	}
210	
211	/**
212	 * The material the buildings are lit with.
213	 *
214	 * Walls are dark glass carrying a procedural window grid: a cell is lit when a
215	 * hash of its position, its wall face and the building's own seed falls under
216	 * that building's lit fraction, so a larger file lights more of its tower and
217	 * the same file lights the same windows in every render. The roof is dark with
218	 * a glowing parapet, and the window light carries the file's language colour
219	 * at low saturation.
220	 * @returns A new building material; the layer owns its own instance.
221	 */
222	function createBuildingMaterial(): ShaderMaterial {
223	  return new ShaderMaterial({
224	    fog: true,
225	    uniforms: UniformsUtils.merge([
226	      UniformsLib.fog,
227	      {
228	        uTime: { value: 0 },
229	        uMotion: { value: 1 },
230	        uCell: { value: WINDOW_CELL },
231	      },
232	    ]),
233	    vertexShader: /* glsl */`
234	      attribute vec3 aTint;
235	      attribute vec3 aInfo;
236	      varying vec3 vTint;
237	      varying vec3 vInfo;
238	      varying vec3 vLocal;
239	      varying vec3 vFace;
240	      varying vec3 vScale;
241	      #include <fog_pars_vertex>
242	      void main() {
243	        vTint = aTint;
244	        vInfo = aInfo;
245	        vLocal = position;
246	        vFace = normal;
247	        vScale = vec3(
248	          length(instanceMatrix[0].xyz),
249	          length(instanceMatrix[1].xyz),
250	          length(instanceMatrix[2].xyz)
251	        );
252	        vec4 mvPosition = modelViewMatrix * instanceMatrix * vec4(position, 1.0);
253	        gl_Position = projectionMatrix * mvPosition;
254	        #include <fog_vertex>
255	      }
256	    `,
257	    fragmentShader: /* glsl */`
258	      uniform float uTime;
259	      uniform float uMotion;
260	      uniform vec2 uCell;
261	      varying vec3 vTint;
262	      varying vec3 vInfo;
263	      varying vec3 vLocal;
264	      varying vec3 vFace;
265	      varying vec3 vScale;
266	      #include <fog_pars_fragment>
267	
268	      float hash21(vec2 p) {
269	        return fract(sin(dot(p, vec2(41.317, 289.113))) * 43758.5453);
270	      }
271	
272	      void main() {
273	        vec3 face = normalize(vFace);
274	        float lit = vInfo.x;
275	        float seed = vInfo.y;
276	        float selected = vInfo.z;
277	
278	        vec3 glassDark = mix(vec3(0.014, 0.022, 0.04), vTint * 0.08, 0.45);
279	        vec3 colour = glassDark;
280	
281	        if (face.y > 0.5) {
282	          float edge = max(abs(vLocal.x), abs(vLocal.z)) * 2.0;
283	          float rim = smoothstep(0.82, 1.0, edge);
284	          colour = vec3(0.011, 0.017, 0.029) + (vTint * rim * (0.26 + (selected * 0.7)));
285	        } else if (face.y < -0.5) {
286	          colour = vec3(0.006, 0.009, 0.017);
287	        } else {
288	          float horizontal = abs(face.x) > 0.5 ? vLocal.z * vScale.z : vLocal.x * vScale.x;
289	          float vertical = (vLocal.y + 0.5) * vScale.y;
290	          vec2 grid = vec2(horizontal / uCell.x, vertical / uCell.y);
291	          vec2 cell = floor(grid);
292	          vec2 inCell = fract(grid);
293	          float wall = abs(face.x) > 0.5 ? 0.0 : 1.0;
294	          float draw = hash21(cell + vec2(seed * 137.0, wall * 19.0));
295	          float on = step(draw, lit);
296	          float pane = step(0.16, inCell.x) * step(inCell.x, 0.84)
297	            * step(0.22, inCell.y) * step(inCell.y, 0.82);
298	          // A handful of windows breathe; the rest hold, so the city never shimmers.
299	          float breath = 1.0 - (uMotion * 0.34 * step(0.9, draw)
300	            * (0.5 + (0.5 * sin((uTime * 1.1) + (draw * 60.0)))));
301	          // Each window keeps its own brightness, so a wall reads as many
302	          // offices rather than as one panel.
303	          float lamp = 0.35 + (0.65 * hash21(cell + vec2(seed * 71.0, 7.3)));
304	          vec3 pool = mix(vec3(1.0), vTint, 0.86);
305	          colour = glassDark + (pool * on * pane * lamp * breath * (0.72 + (selected * 0.6)));
306	          colour += vec3(0.01, 0.015, 0.026) * (1.0 - pane);
307	        }
308	
309	        float key = max(dot(face, normalize(vec3(0.42, 0.82, 0.39))), 0.0);
310	        colour += glassDark * key * 0.9;
311	        colour += vTint * selected * 0.06;
312	
313	        gl_FragColor = vec4(colour, 1.0);
314	        #include <tonemapping_fragment>
315	        #include <colorspace_fragment>
316	        #include <fog_fragment>
317	      }
318	    `,
319	  })
320	}
321	
322	/**
323	 * The material the beacon shafts are drawn with: an additive tube that fades
324	 * upward and glows at its silhouette, so the shaft reads as a column of light
325	 * rather than as geometry. Distance fades it into the city's own fog.
326	 * @returns A new beacon material; the layer owns its own instance.
327	 */
328	function createBeaconMaterial(): ShaderMaterial {
329	  return new ShaderMaterial({
330	    fog: true,
331	    transparent: true,
332	    depthWrite: false,
333	    side: DoubleSide,
334	    blending: AdditiveBlending,
335	    toneMapped: false,
336	    uniforms: UniformsUtils.merge([UniformsLib.fog, {}]),
337	    vertexShader: /* glsl */`
338	      attribute vec3 aColor;
339	      attribute vec2 aInfo;
340	      varying vec3 vColor;
341	      varying float vGain;
342	      varying float vUp;
343	      varying float vRim;
344	      #include <fog_pars_vertex>
345	      void main() {
346	        vColor = aColor;
347	        vGain = aInfo.x * (1.0 + (aInfo.y * 1.15));
348	        vUp = position.y + 0.5;
349	        vec4 mvPosition = modelViewMatrix * instanceMatrix * vec4(position, 1.0);
350	        vec3 viewNormal = normalize(mat3(modelViewMatrix) * mat3(instanceMatrix) * normal);
351	        vRim = 1.0 - abs(dot(viewNormal, normalize(-mvPosition.xyz)));
352	        gl_Position = projectionMatrix * mvPosition;
353	        #include <fog_vertex>
354	      }
355	    `,
356	    fragmentShader: /* glsl */`
357	      varying vec3 vColor;
358	      varying float vGain;
359	      varying float vUp;
360	      varying float vRim;
361	      #include <fog_pars_fragment>
362	      void main() {
363	        float fade = pow(1.0 - vUp, 1.5);
364	        float edge = pow(clamp(vRim, 0.0, 1.0), 1.7);
365	        float foot = smoothstep(0.14, 0.0, vUp) * 0.8;
366	        float alpha = ((fade * (0.2 + (0.95 * edge))) + foot) * vGain * 0.62;
367	        #ifdef USE_FOG
368	          alpha *= 1.0 - smoothstep(fogNear, fogFar, vFogDepth);
369	        #endif
370	        if (alpha < 0.003) discard;
371	        gl_FragColor = vec4(vColor * (0.8 + (0.85 * edge)), alpha);
372	      }
373	    `,
374	  })
375	}
376	
377	/**
378	 * The material the halo at a beacon's foot is drawn with: an additive ring
379	 * that breathes on the clock, one phase per finding.
380	 * @returns A new halo material; the layer owns its own instance.
381	 */
382	function createHaloMaterial(): ShaderMaterial {
383	  return new ShaderMaterial({
384	    fog: true,
385	    transparent: true,
386	    depthWrite: false,
387	    blending: AdditiveBlending,
388	    toneMapped: false,
389	    uniforms: UniformsUtils.merge([UniformsLib.fog, { uTime: { value: 0 }, uMotion: { value: 1 } }]),
390	    vertexShader: /* glsl */`
391	      attribute vec3 aColor;
392	      attribute vec2 aInfo;
393	      varying vec3 vColor;
394	      varying vec2 vInfo;
395	      varying vec2 vUv;
396	      #include <fog_pars_vertex>
397	      void main() {
398	        vColor = aColor;
399	        vInfo = aInfo;
400	        vUv = uv;
401	        vec4 mvPosition = modelViewMatrix * instanceMatrix * vec4(position, 1.0);
402	        gl_Position = projectionMatrix * mvPosition;
403	        #include <fog_vertex>
404	      }
405	    `,
406	    fragmentShader: /* glsl */`
407	      uniform float uTime;
408	      uniform float uMotion;
409	      varying vec3 vColor;
410	      varying vec2 vInfo;
411	      varying vec2 vUv;
412	      #include <fog_pars_fragment>
413	      void main() {
414	        float d = length(vUv - 0.5) * 2.0;
415	        float breath = mix(0.62, 0.58 + (0.42 * sin((uTime * 1.9) + vInfo.y)), uMotion);
416	        float radius = 0.5 + (0.34 * breath);
417	        float ring = smoothstep(radius + 0.28, radius, d) * smoothstep(radius - 0.32, radius, d);
418	        float core = smoothstep(0.42, 0.0, d) * 0.5;
419	        float alpha = ((ring * 1.05) + core) * vInfo.x * breath;
420	        #ifdef USE_FOG
421	          alpha *= 1.0 - smoothstep(fogNear, fogFar, vFogDepth);
422	        #endif
423	        if (alpha < 0.003) discard;
424	        gl_FragColor = vec4(vColor, alpha);
425	      }
426	    `,
427	  })
428	}
429	
430	/**
431	 * The material the scan sweep is drawn with: a wall of light, brightest where
432	 * it meets the ground and fading with height, with scan lines that only travel
433	 * when motion is allowed.
434	 * @returns A new sweep material.
435	 */
436	function createSweepMaterial(): ShaderMaterial {
437	  return new ShaderMaterial({
438	    transparent: true,
439	    depthWrite: false,
440	    side: DoubleSide,
441	    blending: AdditiveBlending,
442	    toneMapped: false,
443	    uniforms: {
444	      uTime: { value: 0 },
445	      uMotion: { value: 1 },
446	      uColor: { value: new Color('#4fd8ff') },
447	    },
448	    vertexShader: /* glsl */`
449	      varying vec2 vUv;
450	      void main() {
451	        vUv = uv;
452	        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
453	      }
454	    `,
455	    fragmentShader: /* glsl */`
456	      uniform float uTime;
457	      uniform float uMotion;
458	      uniform vec3 uColor;
459	      varying vec2 vUv;
460	      void main() {
461	        float rise = pow(1.0 - vUv.y, 2.8);
462	        float ground = smoothstep(0.05, 0.0, vUv.y);
463	        float ends = smoothstep(0.0, 0.07, vUv.x) * smoothstep(1.0, 0.93, vUv.x);
464	        float lines = 0.72 + (0.28 * sin((vUv.y * 190.0) - (uTime * 2.6 * uMotion)));
465	        float alpha = ((rise * 0.26 * lines) + (ground * 0.85)) * ends;
466	        if (alpha < 0.003) discard;
467	        gl_FragColor = vec4(uColor * (0.85 + (ground * 1.2)), alpha);
468	      }
469	    `,
470	  })
471	}
472	
473	/**
474	 * The file blocks, as one instanced mesh of lit towers.
475	 * @param props - The laid-out city, the selection, and the pointer callbacks.
476	 * @returns The city blocks.
477	 */
478	function NightBlocks({
479	  city,
480	  selectedPath,
481	  reduced,
482	  onHover,
483	  onSelect,
484	}: {
485	  city: CityLayout
486	  selectedPath: string | undefined
487	  reduced: boolean
488	  onHover: (block: CityBlock | undefined) => void
489	  onSelect: (block: CityBlock) => void
490	}): ReactNode {
491	  const mesh = useRef<InstancedMesh>(null)
492	  const blocks = city.blocks
493	  const count = Math.max(1, blocks.length)
494	
495	  const geometry = useMemo(() => {
496	    const built = new BoxGeometry(1, 1, 1)
497	    built.setAttribute('aTint', new InstancedBufferAttribute(new Float32Array(count * 3), 3))
498	    built.setAttribute('aInfo', new InstancedBufferAttribute(new Float32Array(count * 3), 3))
499	    return built
500	  }, [count])
501	
502	  const material = useMemo(createBuildingMaterial, [])
503	
504	  useEffect(() => () => {
505	    geometry.dispose()
506	    material.dispose()
507	  }, [geometry, material])
508	
509	  useEffect(() => {
510	    const instanced = mesh.current
511	    if (instanced === null) return
512	    const tint = geometry.getAttribute('aTint')
513	    const info = geometry.getAttribute('aInfo')
514	    const colour = new Color()
515	    for (const [index, block] of blocks.entries()) {
516	      SCRATCH_SCALE.set(block.size, block.height, block.size)
517	      SCRATCH_POSITION.set(block.x, block.height / 2, block.z)
518	      SCRATCH.identity().scale(SCRATCH_SCALE).setPosition(SCRATCH_POSITION)
519	      instanced.setMatrixAt(index, SCRATCH)
520	      colour.set(languageColor(block.language))
521	      tint.setXYZ(index, colour.r, colour.g, colour.b)
522	      info.setXYZ(index, block.lit, block.seed, block.path === selectedPath ? 1 : 0)
523	    }
524	    instanced.instanceMatrix.needsUpdate = true
525	    tint.needsUpdate = true
526	    info.needsUpdate = true
527	  }, [blocks, selectedPath, geometry])
528	
529	  useEffect(() => {
530	    material.uniforms.uMotion!.value = reduced ? 0 : 1
531	  }, [material, reduced])
532	
533	  useFrame(({ clock }) => {
534	    if (reduced) return
535	    material.uniforms.uTime!.value = clock.elapsedTime
536	  })
537	
538	  return (
539	    <instancedMesh
540	      ref={mesh}
541	      args={[undefined, undefined, count]}
542	      geometry={geometry}
543	      material={material}
544	      onPointerMove={(event: ThreeEvent<PointerEvent>) => {
545	        event.stopPropagation()
546	        const block = event.instanceId === undefined ? undefined : blocks[event.instanceId]
547	        onHover(block)
548	        document.body.style.cursor = block === undefined ? 'auto' : 'pointer'
549	      }}
550	      onPointerOut={() => {
551	        onHover(undefined)
552	        document.body.style.cursor = 'auto'
553	      }}
554	      onClick={(event: ThreeEvent<MouseEvent>) => {
555	        event.stopPropagation()
556	        const block = event.instanceId === undefined ? undefined : blocks[event.instanceId]
557	        if (block !== undefined) onSelect(block)
558	      }}
559	    />
560	  )
561	}
562	
563	/**
564	 * The district plates, their glowing outlines and their directory names. The
565	 * outlines pulse while the review is still running.
566	 * @param props - The laid-out city, whether a department is still out, and the
567	 * motion preference.
568	 * @returns The plates, the outlines and the labels.
569	 */
570	function Districts({
571	  city,
572	  running,
573	  reduced,
574	}: {
575	  city: CityLayout
576	  running: boolean
577	  reduced: boolean
578	}): ReactNode {
579	  const plates = useRef<InstancedMesh>(null)
580	  const outline = useRef<LineBasicMaterial>(null)
581	
582	  const outlineGeometry = useMemo(() => {
583	    const built = new BufferGeometry()
584	    const positions = new Float32Array(city.districts.length * 24)
585	    const colors = new Float32Array(city.districts.length * 24)
586	    const colour = new Color()
587	    for (const [index, district] of city.districts.entries()) {
588	      const left = district.x - (district.width / 2)
589	      const right = district.x + (district.width / 2)
590	      const near = district.z - (district.depth / 2)
591	      const far = district.z + (district.depth / 2)
592	      const corners: [number, number][] = [[left, near], [right, near], [right, far], [left, far]]
593	      colour.set(languageColor(district.language))
594	      for (let edge = 0; edge < 4; edge += 1) {
595	        const from = corners[edge]!
596	        const to = corners[(edge + 1) % 4]!
597	        const offset = (index * 24) + (edge * 6)
598	        positions.set([from[0], 0.02, from[1], to[0], 0.02, to[1]], offset)
599	        colors.set([colour.r, colour.g, colour.b, colour.r, colour.g, colour.b], offset)
600	      }
601	    }
602	    built.setAttribute('position', new BufferAttribute(positions, 3))
603	    built.setAttribute('color', new BufferAttribute(colors, 3))
604	    return built
605	  }, [city])
606	
607	  useEffect(() => () => outlineGeometry.dispose(), [outlineGeometry])
608	
609	  useEffect(() => {
610	    const instanced = plates.current
611	    if (instanced === null) return
612	    for (const [index, district] of city.districts.entries()) {
613	      SCRATCH_SCALE.set(district.width, 0.5, district.depth)
614	      SCRATCH_POSITION.set(district.x, -0.26, district.z)
615	      SCRATCH.identity().scale(SCRATCH_SCALE).setPosition(SCRATCH_POSITION)
616	      instanced.setMatrixAt(index, SCRATCH)
617	    }
618	    instanced.instanceMatrix.needsUpdate = true
619	  }, [city])
620	
621	  useFrame(({ clock }) => {
622	    const material = outline.current
623	    if (material === null) return
624	    if (!running) {
625	      material.opacity = 0.38
626	      return
627	    }
628	    material.opacity = reduced
629	      ? 0.56
630	      : 0.3 + (0.36 * ((Math.sin(clock.elapsedTime * 1.7) * 0.5) + 0.5))
631	  })
632	
633	  return (
634	    <group>
635	      <instancedMesh ref={plates} args={[undefined, undefined, Math.max(1, city.districts.length)]}>
636	        <boxGeometry args={[1, 1, 1]} />
637	        <meshStandardMaterial color="#080e1a" roughness={0.94} metalness={0.06} />
638	      </instancedMesh>
639	
640	      <lineSegments geometry={outlineGeometry} frustumCulled={false}>
641	        <lineBasicMaterial
642	          ref={outline}
643	          vertexColors
644	          transparent
645	          opacity={0.38}
646	          blending={AdditiveBlending}
647	          depthWrite={false}
648	          toneMapped={false}
649	        />
650	      </lineSegments>
651	
652	      {city.districts.map(district => (
653	        <Html
654	          key={district.path}
655	          center
656	          position={[district.x, 0.4, district.z + (district.depth / 2) + 1.8]}
657	          zIndexRange={[10, 3]}
658	          style={{ pointerEvents: 'none' }}
659	        >
660	          <div className={styles.districtLabel} style={{ color: languageColor(district.language) }}>
661	            {district.path}
662	          </div>
663	        </Html>
664	      ))}
665	    </group>
666	  )
667	}
