669	/**
670	 * The finding beacons: one light shaft per finding, a breathing halo at each
671	 * foot, and the marker head that carries the hover and the click.
672	 * @param props - The placed findings, the selection, the motion preference and
673	 * the pointer callbacks.
674	 * @returns The beacon layers.
675	 */
676	function Beacons({
677	  placed,
678	  selectedId,
679	  reduced,
680	  onHover,
681	  onSelect,
682	}: {
683	  placed: PlacedFinding[]
684	  selectedId: string | undefined
685	  reduced: boolean
686	  onHover: (entry: PlacedFinding | undefined) => void
687	  onSelect: (id: string) => void
688	}): ReactNode {
689	  const shafts = useRef<InstancedMesh>(null)
690	  const halos = useRef<InstancedMesh>(null)
691	  const count = Math.max(1, placed.length)
692	
693	  const shaftGeometry = useMemo(() => {
694	    const built = new CylinderGeometry(1, 1, 1, 7, 1, true)
695	    built.setAttribute('aColor', new InstancedBufferAttribute(new Float32Array(count * 3), 3))
696	    built.setAttribute('aInfo', new InstancedBufferAttribute(new Float32Array(count * 2), 2))
697	    return built
698	  }, [count])
699	
700	  const haloGeometry = useMemo(() => {
701	    const built = new CircleGeometry(1, 22)
702	    built.rotateX(-Math.PI / 2)
703	    built.setAttribute('aColor', new InstancedBufferAttribute(new Float32Array(count * 3), 3))
704	    built.setAttribute('aInfo', new InstancedBufferAttribute(new Float32Array(count * 2), 2))
705	    return built
706	  }, [count])
707	
708	  const headGeometry = useMemo(() => {
709	    const built = new BufferGeometry()
710	    built.setAttribute('position', new BufferAttribute(new Float32Array(placed.length * 3), 3))
711	    built.setAttribute('aColor', new BufferAttribute(new Float32Array(placed.length * 3), 3))
712	    built.setAttribute('aSize', new BufferAttribute(new Float32Array(placed.length), 1))
713	    built.setAttribute('aGain', new BufferAttribute(new Float32Array(placed.length), 1))
714	    return built
715	  }, [placed.length])
716	
717	  const shaftMaterial = useMemo(createBeaconMaterial, [])
718	  const haloMaterial = useMemo(createHaloMaterial, [])
719	  const headMaterial = useMemo(createGlowMaterial, [])
720	
721	  useEffect(() => () => {
722	    shaftGeometry.dispose()
723	    haloGeometry.dispose()
724	    headGeometry.dispose()
725	    shaftMaterial.dispose()
726	    haloMaterial.dispose()
727	    headMaterial.dispose()
728	  }, [shaftGeometry, haloGeometry, headGeometry, shaftMaterial, haloMaterial, headMaterial])
729	
730	  useEffect(() => {
731	    const shaft = shafts.current
732	    const halo = halos.current
733	    if (shaft === null || halo === null) return
734	    const shaftColour = shaftGeometry.getAttribute('aColor')
735	    const shaftInfo = shaftGeometry.getAttribute('aInfo')
736	    const haloColour = haloGeometry.getAttribute('aColor')
737	    const haloInfo = haloGeometry.getAttribute('aInfo')
738	    const headPosition = headGeometry.getAttribute('position')
739	    const headColour = headGeometry.getAttribute('aColor')
740	    const headSize = headGeometry.getAttribute('aSize')
741	    const headGain = headGeometry.getAttribute('aGain')
742	    const colour = new Color()
743	
744	    for (const [index, entry] of placed.entries()) {
745	      const selected = entry.finding.id === selectedId ? 1 : 0
746	      colour.set(SEVERITY_COLOR[entry.finding.severity] ?? '#7f8fb0')
747	
748	      SCRATCH_SCALE.set(entry.radius, entry.height, entry.radius)
749	      SCRATCH_POSITION.set(entry.base.x, entry.base.y + (entry.height / 2), entry.base.z)
750	      SCRATCH.identity().scale(SCRATCH_SCALE).setPosition(SCRATCH_POSITION)
751	      shaft.setMatrixAt(index, SCRATCH)
752	      shaftColour.setXYZ(index, colour.r, colour.g, colour.b)
753	      shaftInfo.setXY(index, entry.gain, selected)
754	
755	      const halved = HALO_RADIUS * (0.7 + (entry.gain * 0.36))
756	      SCRATCH_SCALE.set(halved, 1, halved)
757	      SCRATCH_POSITION.set(entry.base.x, entry.base.y + 0.07, entry.base.z)
758	      SCRATCH.identity().scale(SCRATCH_SCALE).setPosition(SCRATCH_POSITION)
759	      halo.setMatrixAt(index, SCRATCH)
760	      haloColour.setXYZ(index, colour.r, colour.g, colour.b)
761	      haloInfo.setXY(index, entry.gain * (selected === 1 ? 1.9 : 1), index * 1.37)
762	
763	      headPosition.setXYZ(index, entry.head.x, entry.head.y, entry.head.z)
764	      headColour.setXYZ(index, colour.r, colour.g, colour.b)
765	      headSize.setX(index, MARKER_SIZE[entry.finding.severity] ?? 6)
766	      headGain.setX(index, selected === 1 ? 2.2 : 0.8 + (entry.gain * 0.3))
767	    }
768	
769	    shaft.instanceMatrix.needsUpdate = true
770	    halo.instanceMatrix.needsUpdate = true
771	    for (const attribute of [
772	      shaftColour, shaftInfo, haloColour, haloInfo, headPosition, headColour, headSize, headGain,
773	    ]) attribute.needsUpdate = true
774	    headGeometry.computeBoundingSphere()
775	  }, [placed, selectedId, shaftGeometry, haloGeometry, headGeometry])
776	
777	  useEffect(() => {
778	    haloMaterial.uniforms.uMotion!.value = reduced ? 0 : 1
779	  }, [haloMaterial, reduced])
780	
781	  useFrame(({ clock }) => {
782	    if (reduced) return
783	    haloMaterial.uniforms.uTime!.value = clock.elapsedTime
784	  })
785	
786	  return (
787	    <group>
788	      <instancedMesh
789	        ref={shafts}
790	        args={[undefined, undefined, count]}
791	        geometry={shaftGeometry}
792	        material={shaftMaterial}
793	        frustumCulled={false}
794	        renderOrder={2}
795	        onPointerMove={(event: ThreeEvent<PointerEvent>) => {
796	          event.stopPropagation()
797	          const entry = event.instanceId === undefined ? undefined : placed[event.instanceId]
798	          onHover(entry)
799	          document.body.style.cursor = entry === undefined ? 'auto' : 'pointer'
800	        }}
801	        onPointerOut={() => {
802	          onHover(undefined)
803	          document.body.style.cursor = 'auto'
804	        }}
805	        onClick={(event: ThreeEvent<MouseEvent>) => {
806	          event.stopPropagation()
807	          const entry = event.instanceId === undefined ? undefined : placed[event.instanceId]
808	          if (entry !== undefined) onSelect(entry.finding.id)
809	        }}
810	      />
811	
812	      <instancedMesh
813	        ref={halos}
814	        args={[undefined, undefined, count]}
815	        geometry={haloGeometry}
816	        material={haloMaterial}
817	        frustumCulled={false}
818	        renderOrder={1}
819	      />
820	
821	      <points
822	        geometry={headGeometry}
823	        material={headMaterial}
824	        frustumCulled={false}
825	        renderOrder={3}
826	        onClick={(event: ThreeEvent<MouseEvent>) => {
827	          event.stopPropagation()
828	          const entry = event.index === undefined ? undefined : placed[event.index]
829	          if (entry !== undefined) onSelect(entry.finding.id)
830	        }}
831	      />
832	    </group>
833	  )
834	}
