836	/**
837	 * The scan sweep: a wall of light crossing the city while any department is
838	 * still out. Under reduced motion it stands still over the centre instead.
839	 * @param props - The laid-out city and the motion preference.
840	 * @returns The sweep plane.
841	 */
842	function ScanSweep({ city, reduced }: { city: CityLayout; reduced: boolean }): ReactNode {
843	  const plane = useRef<Mesh>(null)
844	  const material = useMemo(createSweepMaterial, [])
845	  const height = city.extent * 0.62
846	  const travel = city.extent * 1.25
847	
848	  useEffect(() => () => material.dispose(), [material])
849	
850	  useEffect(() => {
851	    material.uniforms.uMotion!.value = reduced ? 0 : 1
852	  }, [material, reduced])
853	
854	  useFrame(({ clock }) => {
855	    const mesh = plane.current
856	    if (mesh === null || reduced) return
857	    material.uniforms.uTime!.value = clock.elapsedTime
858	    const phase = clock.elapsedTime % (SWEEP_SECONDS + SWEEP_GAP_SECONDS)
859	    const progress = phase / SWEEP_SECONDS
860	    mesh.visible = progress <= 1
861	    if (mesh.visible) mesh.position.x = -travel + (progress * travel * 2)
862	  })
863	
864	  return (
865	    <mesh
866	      ref={plane}
867	      position={[reduced ? 0 : -travel, height / 2, 0]}
868	      rotation={[0, Math.PI / 2, 0]}
869	      material={material}
870	      renderOrder={4}
871	    >
872	      <planeGeometry args={[city.extent * 2.2, height]} />
873	    </mesh>
874	  )
875	}
