877	/**
878	 * Camera behaviour: the opening fly-over, the flight to a selected finding and
879	 * back, and the orbit controls in between. Under reduced motion every move is
880	 * an instant cut.
881	 * @param props - The city, its beacon reach, the finding to frame, and the
882	 * motion preference.
883	 * @returns The controls.
884	 */
885	function CityRig({
886	  city,
887	  reach,
888	  focus,
889	  reduced,
890	}: {
891	  city: CityLayout
892	  reach: number
893	  focus: PlacedFinding | undefined
894	  reduced: boolean
895	}): ReactNode {
896	  const controls = useRef<ElementRef<typeof OrbitControls>>(null)
897	  const { camera } = useThree()
898	  const flight = useRef<{
899	    fromPosition: Vector3
900	    fromTarget: Vector3
901	    toPosition: Vector3
902	    toTarget: Vector3
903	    elapsed: number
904	    duration: number
905	  } | undefined>(undefined)
906	  const opened = useRef(false)
907	
908	  useEffect(() => {
909	    const control = controls.current
910	    if (control === null) return
911	    const destination = focus === undefined ? cityView(city.extent, reach) : focusView(focus)
912	    const opening = !opened.current
913	    opened.current = true
914	
915	    if (reduced) {
916	      flight.current = undefined
917	      control.enabled = true
918	      camera.position.copy(destination.position)
919	      control.target.copy(destination.target)
920	      control.update()
921	      return
922	    }
923	
924	    if (opening) {
925	      const start = flyoverStart(city.extent, reach)
926	      camera.position.copy(start.position)
927	      control.target.copy(start.target)
928	    }
929	    control.enabled = false
930	    flight.current = {
931	      fromPosition: camera.position.clone(),
932	      fromTarget: control.target.clone(),
933	      toPosition: destination.position,
934	      toTarget: destination.target,
935	      elapsed: 0,
936	      duration: opening ? FLYOVER_SECONDS : FOCUS_SECONDS,
937	    }
938	  }, [focus, city.extent, reach, reduced, camera])
939	
940	  useFrame((_, delta) => {
941	    const control = controls.current
942	    if (control === null) return
943	    const current = flight.current
944	    if (current !== undefined) {
945	      current.elapsed += delta
946	      const progress = Math.min(1, current.elapsed / current.duration)
947	      const eased = easeInOutCubic(progress)
948	      camera.position.lerpVectors(current.fromPosition, current.toPosition, eased)
949	      control.target.lerpVectors(current.fromTarget, current.toTarget, eased)
950	      if (progress >= 1) {
951	        flight.current = undefined
952	        control.enabled = true
953	      }
954	    }
955	    control.update()
956	  })
957	
958	  return (
959	    <OrbitControls
960	      ref={controls}
961	      makeDefault
962	      enableDamping
963	      dampingFactor={0.07}
964	      rotateSpeed={0.45}
965	      zoomSpeed={0.75}
966	      minDistance={14}
967	      maxDistance={cityDistance(city.extent, reach) * 1.35}
968	      maxPolarAngle={Math.PI * 0.47}
969	    />
970	  )
971	}
