973	/**
974	 * The code-city scene.
975	 * @param props - The reviewed target, its departments, its findings, and the
976	 * selection.
977	 * @returns The canvas and its contents.
978	 */
979	export function SafetyStage({
980	  target,
981	  departments,
982	  findings,
983	  selectedFindingId,
984	  onSelectFinding,
985	}: {
986	  target: SafetyTarget
987	  departments: readonly SafetyDepartment[]
988	  findings: readonly Finding[]
989	  selectedFindingId: string | undefined
990	  onSelectFinding: (id: string | undefined) => void
991	}): ReactNode {
992	  const reduced = usePrefersReducedMotion()
993	  const city = useMemo(() => layoutCity(target), [target])
994	  const placed = useMemo(() => placeFindings(findings, city), [findings, city])
995	  // How high the scene actually stands: the tallest beacon, or the tallest
996	  // file where the review found nothing.
997	  const reach = useMemo(
998	    () => placed.reduce(
999	      (acc, entry) => Math.max(acc, entry.base.y + entry.height),
1000	      city.blocks.reduce((acc, block) => Math.max(acc, block.height), 0),
1001	    ),
1002	    [placed, city],
1003	  )
1004	  const view = useMemo(() => cityView(city.extent, reach), [city.extent, reach])
1005	  const [hoveredBlock, setHoveredBlock] = useState<CityBlock | undefined>(undefined)
1006	  const [hoveredFinding, setHoveredFinding] = useState<PlacedFinding | undefined>(undefined)
1007	
1008	  // A department the feed still reports as pending is the one honest signal
1009	  // that the review is running; every other status means it has reported.
1010	  const running = departments.some(entry => entry.status === 'pending')
1011	
1012	  const focus = useMemo(
1013	    () => placed.find(entry => entry.finding.id === selectedFindingId),
1014	    [placed, selectedFindingId],
1015	  )
1016	
1017	  return (
1018	    <Stage
1019	      camera={{ position: [view.position.x, view.position.y, view.position.z], fov: 40 }}
1020	      fogNear={city.extent * 2.2}
1021	      fogFar={city.extent * 8}
1022	    >
1023	      <group>
1024	        <mesh position={[0, -0.72, 0]} rotation={[-Math.PI / 2, 0, 0]}>
1025	          <planeGeometry args={[city.extent * 8, city.extent * 8]} />
1026	          <meshStandardMaterial color="#04070d" roughness={1} metalness={0} />
1027	        </mesh>
1028	        <gridHelper args={[city.extent * 7, 64, '#1a3355', '#0d1b2e']} position={[0, -0.66, 0]} />
1029	
1030	        <Districts city={city} running={running} reduced={reduced} />
1031	        <NightBlocks
1032	          city={city}
1033	          selectedPath={focus?.block.path}
1034	          reduced={reduced}
1035	          onHover={setHoveredBlock}
1036	          onSelect={(block) => {
1037	            const first = placed.find(entry => entry.block.path === block.path)
1038	            if (first !== undefined) onSelectFinding(first.finding.id)
1039	          }}
1040	        />
1041	        <Beacons
1042	          placed={placed}
1043	          selectedId={selectedFindingId}
1044	          reduced={reduced}
1045	          onHover={setHoveredFinding}
1046	          onSelect={onSelectFinding}
1047	        />
1048	        {running ? <ScanSweep city={city} reduced={reduced} /> : null}
1049	
1050	        {hoveredFinding === undefined || hoveredFinding.finding.id === selectedFindingId ? null : (
1051	          <Html
1052	            center
1053	            position={[hoveredFinding.head.x, hoveredFinding.head.y + 1.7, hoveredFinding.head.z]}
1054	            zIndexRange={[40, 20]}
1055	            style={{ pointerEvents: 'none' }}
1056	          >
1057	            <div className={styles.hoverLabel}>
1058	              <b>{hoveredFinding.finding.file}:{hoveredFinding.finding.line}</b>
1059	              <span>{hoveredFinding.finding.severity}</span>
1060	              <em>{hoveredFinding.finding.title}</em>
1061	            </div>
1062	          </Html>
1063	        )}
1064	
1065	        {hoveredFinding !== undefined || hoveredBlock === undefined ? null : (
1066	          <Html
1067	            center
1068	            position={[hoveredBlock.x, hoveredBlock.height + 1.6, hoveredBlock.z]}
1069	            zIndexRange={[40, 20]}
1070	            style={{ pointerEvents: 'none' }}
1071	          >
1072	            <div className={styles.hoverLabel}>
1073	              <b>{hoveredBlock.path}</b>
1074	              <span>{hoveredBlock.language}</span>
1075	            </div>
1076	          </Html>
1077	        )}
1078	
1079	        {focus === undefined ? null : (
1080	          <Html
1081	            position={calloutAnchor(focus).toArray()}
1082	            zIndexRange={[60, 40]}
1083	            style={{ pointerEvents: 'none' }}
1084	          >
1085	            <div
1086	              className={styles.callout}
1087	              style={{ color: SEVERITY_COLOR[focus.finding.severity] ?? '#7f8fb0' }}
1088	            >
1089	              <div className={styles.calloutHead}>
1090	                <span className={styles.calloutPill}>{focus.finding.severity}</span>
1091	                <span>{focus.finding.cwe}</span>
1092	              </div>
1093	              <div className={styles.calloutWhere}>{focus.finding.file}:{focus.finding.line}</div>
1094	              <div className={styles.calloutTitle}>{focus.finding.title}</div>
1095	            </div>
1096	          </Html>
1097	        )}
1098	      </group>
1099	
1100	      <CityRig city={city} reach={reach} focus={focus} reduced={reduced} />
1101	    </Stage>
1102	  )
1103	}
