for(const p of inv){const b=p.slice(p.lastIndexOf('/')+1); (byBase.get(b)??byBase.set(b,[]).get(b)).push(p);}
const TOK=/(?:<path>([^<]+)<\/path>)|(\/[A-Za-z0-9._\/-]+)/g;
function resolve(detail){
  if(!detail) return undefined;
  let best; let bestLen=-1;
  let m; TOK.lastIndex=0;
  while((m=TOK.exec(detail))!==null){
    const raw=(m[1]??m[2]).trim();
    const b=raw.slice(raw.lastIndexOf('/')+1);
    const cands=byBase.get(b); if(!cands) continue;
    for(const p of cands){
      if(raw===p || raw.endsWith('/'+p)){ if(p.length>bestLen){bestLen=p.length;best=p;} }
    }
