  return best;
}
let hits=0, tools=0, uniq=new Set(), perLabel={};
for(const e of lines){ if(e.kind!=='tool') continue; tools++; const r=resolve(e.detail); if(r){hits++;uniq.add(r);perLabel[e.label]=(perLabel[e.label]||0)+1;} }
