(async () => {
  const canvas = document.querySelector('canvas')
  const rect = canvas.getBoundingClientRect()
  const out = { rect: [rect.left, rect.top, rect.width, rect.height], hits: 0, cursor: [], classes: [] }
  const move = (x, y, target) => {
    const event = new PointerEvent('pointermove', {
      clientX: x, clientY: y, bubbles: true, cancelable: true,
      pointerId: 1, pointerType: 'mouse', isPrimary: true, buttons: 0,
    })
    Object.defineProperty(event, 'offsetX', { value: x - rect.left })
    Object.defineProperty(event, 'offsetY', { value: y - rect.top })
    target.dispatchEvent(event)
  }
  for (let y = rect.top + 120; y < rect.bottom - 180; y += 13) {
    for (let x = rect.left + 120; x < rect.right - 120; x += 13) {
      move(x, y, canvas)
      if (document.body.style.cursor === 'pointer') {
        out.hits += 1
        out.cursor.push([Math.round(x), Math.round(y)])
        if (out.hits > 3) {
          await new Promise(resolve => setTimeout(resolve, 800))
          out.classes = [...document.querySelectorAll('div')]
            .map(node => node.className)
            .filter(name => typeof name === 'string' && name.includes('safety'))
            .slice(0, 6)
          return JSON.stringify(out)
        }
      }
    }
  }
  return JSON.stringify(out)
})()

