// Interleaved A/B frame-cost probe over CDP: 90-frame windows, 5 rounds, SwiftShader.
// usage: node perf.mjs <urlA> <urlB> [rounds] [settleMs]
import { spawn } from 'node:child_process'
import { setTimeout as sleep } from 'node:timers/promises'

const [, , urlA, urlB, roundsArg, settleArg] = process.argv
const rounds = Number(roundsArg ?? 5)
const settle = Number(settleArg ?? 9000)
const PORT = 9341

const chrome = spawn('/opt/pw-browsers/chromium', [
  '--headless=new',
  '--no-sandbox',
  '--disable-dev-shm-usage',
  '--enable-unsafe-swiftshader',
  '--hide-scrollbars',
  '--force-device-scale-factor=1',
  '--window-size=1600,1000',
  `--remote-debugging-port=${PORT}`,
  'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] })
