// A stand-in feed on 4712 that plays the recorded NodeGoat review through its
// phases, so the Safety view's launch sequence, read trail and verdict can be
// exercised without starting a real review. Reads phase from a file so the
// phase can be flipped while the deck is watching.
//   0 = just started, every department pending, nothing released
//   1 = running, three departments released
//   2 = finished and certified (as the record actually ended)
//   3 = finished with the certificate withheld
import { createServer } from 'node:http'
import { readFileSync } from 'node:fs'

const UPSTREAM = 'http://localhost:4711'
const RUN = '2026-09-19-nodegoat-2'
const EVENTS = '/home/user/deepseek-harness/.claude/worktrees/agent-a8add07bf87d79a5d/apps/command-deck/fixtures/events/2026-09-19-nodegoat-2.jsonl'
const PHASE_FILE = '/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/wave2-safety/phase'
const RELEASED = new Set(['secrets', 'injection', 'access'])
const START = new Date()

const headers = {
  'access-control-allow-origin': '*',
  'content-type': 'application/json',
  'cache-control': 'no-store',
}

const recorded = readFileSync(EVENTS, 'utf8').split('\n').filter(line => line.trim() !== '')

function phase() {
  try {
    return Number(readFileSync(PHASE_FILE, 'utf8').trim())
  } catch {
    return 0
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url ?? '/', 'http://localhost')
  const at = phase()
  try {
    if (url.pathname === `/runs/${RUN}/events`) {
      response.writeHead(200, {
        'access-control-allow-origin': '*',
        'content-type': 'text/event-stream; charset=utf-8',
        'cache-control': 'no-cache, no-transform',
        connection: 'keep-alive',
      })
      let cursor = 0
      const pace = Number(process.env.PACE_MS ?? 120)
      const timer = setInterval(() => {
        if (cursor >= recorded.length) return
        response.write(`data: ${recorded[cursor]}\n\n`)
        cursor += 1
      }, pace)
      request.on('close', () => clearInterval(timer))
      return
    }

    if (url.pathname === '/runs') {
      const runs = await (await fetch(`${UPSTREAM}/runs`)).json()
      const patched = runs.map(run => (run.id === RUN
        ? (at < 2
            ? { ...run, status: 'running', startedAt: START.toISOString(), endedAt: undefined }
            : { ...run, status: 'completed', startedAt: START.toISOString() })
        : run))
      // The deck follows the first code-safety run it is given.
      patched.sort((left, right) => (left.id === RUN ? -1 : right.id === RUN ? 1 : 0))
      response.writeHead(200, headers)
      response.end(JSON.stringify(patched))
      return
    }

    if (url.pathname.startsWith('/safety/')) {
      const detail = await (await fetch(`${UPSTREAM}/safety/${RUN}`)).json()
      if (at >= 2) {
        const withheld = at === 3
        response.writeHead(200, headers)
        response.end(JSON.stringify(withheld
          ? {
              ...detail,
              departments: detail.departments.map((d, i) => (i > 3 ? { ...d, certified: false } : d)),
              certificate: {
                ...detail.certificate,
                verified: false,
                unverified: detail.findings.slice(0, 3).map(f => f.id),
              },
            }
          : detail))
        return
      }
      const released = at === 0 ? new Set() : RELEASED
      const findings = detail.findings.filter(f => released.has(String(f.id).split('-')[0]))
      const departments = detail.departments.map(department => (released.has(department.id)
        ? { ...department, certified: false }
        : { ...department, status: 'pending', certified: false, findings: 0 }))
      const counts = { critical: 0, high: 0, medium: 0, low: 0, info: 0 }
      for (const finding of findings) counts[finding.severity] += 1
      response.writeHead(200, headers)
      response.end(JSON.stringify({
        ...detail,
        findings,
        departments,
        certificate: { ...detail.certificate, verified: false, counts, unverified: [] },
      }))
      return
    }

    const upstream = await fetch(`${UPSTREAM}${url.pathname}${url.search}`)
    response.writeHead(upstream.status, {
      ...headers,
      'content-type': upstream.headers.get('content-type') ?? 'application/json',
    })
    response.end(Buffer.from(await upstream.arrayBuffer()))
  } catch (error) {
    response.writeHead(500, headers)
    response.end(JSON.stringify({ error: String(error) }))
  }
})

