1	/* The two set pieces the Safety view plays over the code city: the launch
2	   sequence that ignites the six departments, and the verdict the certificate
3	   lands as. Both hold the frame for a fixed time and are unmounted by their
4	   own timer, so the last thing each animation does is fade itself out. */
5	
6	.overlay {
7	  position: absolute;
8	  inset: 0;
9	  z-index: 46;
10	  pointer-events: none;
11	  display: grid;
12	  place-items: center;
13	  padding: 0 28px;
14	}
15	
16	.eyebrow {
17	  font-family: var(--font-mono);
18	  font-size: 9.5px;
19	  text-transform: uppercase;
20	  letter-spacing: 0.32em;
21	  color: var(--ink-3);
22	}
23	
24	/* ------------------------------------------------------------- launch -- */
25	
26	.launch {
27	  background: radial-gradient(
28	    86% 70% at 50% 46%,
29	    rgba(4, 6, 11, 0.95) 0%,
30	    rgba(4, 6, 11, 0.86) 40%,
31	    rgba(4, 6, 11, 0.56) 70%,
32	    rgba(4, 6, 11, 0.18) 100%
33	  );
34	  animation: veil 8000ms linear forwards;
35	}
36	
37	.launch[data-reduced='true'] { animation: none; }
38	
39	.launchInner {
40	  width: min(660px, 100%);
41	}
42	
43	.launchHead {
44	  display: flex;
45	  align-items: baseline;
46	  justify-content: space-between;
47	  gap: 16px;
48	  padding-bottom: 11px;
49	  border-bottom: 1px solid var(--line);
50	}
51	
52	.launchTitle {
53	  margin: 0;
54	  font-size: 21px;
55	  font-weight: 300;
56	  letter-spacing: -0.01em;
57	  color: var(--ink);
58	}
59	
60	.row {
61	  display: grid;
62	  grid-template-columns: 16px 132px 1fr;
63	  align-items: baseline;
64	  gap: 12px;
65	  padding: 11px 0 10px;
66	  border-bottom: 1px solid rgba(122, 152, 205, 0.09);
67	  animation: ignite 900ms cubic-bezier(0.22, 0.85, 0.3, 1) backwards;
68	  animation-delay: calc(var(--i, 0) * 820ms);
69	}
70	
71	.launch[data-reduced='true'] .row { animation: none; }
72	
73	.rowMark {
74	  width: 7px;
75	  height: 7px;
76	  border-radius: 50%;
77	  background: currentColor;
78	  box-shadow: 0 0 14px currentColor;
79	}
80	
81	.rowName {
82	  font-size: 14px;
83	  letter-spacing: 0.02em;
84	  color: currentColor;
85	}
86	
87	.rowCharter {
88	  font-size: 12px;
89	  line-height: 1.45;
90	  color: var(--ink-2);
91	}
92	
93	/* ------------------------------------------------------------ verdict -- */
94	
95	.verdict {
96	  z-index: 48;
97	  text-align: center;
98	  background: radial-gradient(
99	    78% 62% at 50% 50%,
100	    rgba(4, 6, 11, 0.94) 0%,
101	    rgba(4, 6, 11, 0.78) 36%,
102	    rgba(4, 6, 11, 0.36) 66%,
103	    rgba(4, 6, 11, 0) 88%
104	  );
105	  animation: veil 10000ms linear forwards;
106	}
107	
108	.verdict[data-reduced='true'] { animation: none; }
109	
110	.verdictTitle {
111	  margin: 14px 0 0;
112	  font-size: clamp(40px, 7.4vw, 104px);
113	  font-weight: 300;
114	  line-height: 1;
115	  letter-spacing: 0.01em;
116	  color: currentColor;
117	  text-shadow: 0 0 74px currentColor;
118	}
119	
120	.char {
121	  display: inline-block;
122	  animation: strike 620ms cubic-bezier(0.19, 0.9, 0.24, 1) backwards;
123	  animation-delay: calc(var(--i, 0) * 32ms);
124	}
125	
126	.verdict[data-reduced='true'] .char { animation: none; }
127	
128	.verdictLine {
129	  margin: 20px 0 0;
130	  font-size: 14.5px;
131	  color: var(--ink-2);
132	  animation: rise 700ms ease-out backwards;
133	  animation-delay: calc(700ms + var(--i, 0) * 150ms);
134	}
135	
136	.verdict[data-reduced='true'] .verdictLine { animation: none; }
137	
138	.verdictWhere {
139	  display: block;
140	  margin-top: 5px;
141	  font-family: var(--font-mono);
142	  font-size: 11.5px;
143	  color: var(--ink-3);
144	}
145	
146	.tally {
147	  display: flex;
148	  justify-content: center;
149	  gap: 26px;
150	  margin-top: 26px;
151	  animation: rise 700ms ease-out backwards;
152	  animation-delay: 1250ms;
153	}
154	
155	.verdict[data-reduced='true'] .tally { animation: none; }
156	
157	.tally div {
158	  display: grid;
159	  gap: 2px;
160	}
161	
162	.tally b {
163	  font-size: 26px;
164	  font-weight: 400;
165	  line-height: 1;
166	}
167	
168	.tally span {
169	  font-family: var(--font-mono);
170	  font-size: 9px;
171	  text-transform: uppercase;
172	  letter-spacing: 0.16em;
173	  color: var(--ink-3);
174	}
175	
176	@keyframes veil {
177	  0% { opacity: 0; }
178	  4% { opacity: 1; }
179	  88% { opacity: 1; }
180	  100% { opacity: 0; }
181	}
182	
183	@keyframes ignite {
184	  from { opacity: 0; transform: translate3d(-14px, 0, 0); filter: blur(5px); }
185	  to { opacity: 1; transform: none; filter: blur(0); }
186	}
187	
188	@keyframes strike {
189	  from { opacity: 0; transform: translate3d(0, 0.3em, 0) scale(1.14); filter: blur(6px); }
190	  to { opacity: 1; transform: none; filter: blur(0); }
191	}
192	
193	@keyframes rise {
194	  from { opacity: 0; transform: translate3d(0, 10px, 0); }
195	  to { opacity: 1; transform: none; }
196	}

