const fs=require('fs');
const safety=JSON.parse(fs.readFileSync('fixtures/safety/2026-09-19-nodegoat-2.json','utf8'));
const byBase=new Map();
for(const f of safety.target.files){const b=f.path.slice(f.path.lastIndexOf('/')+1); if(!byBase.has(b))byBase.set(b,[]); byBase.get(b).push(f.path);}
const TAG=/<path>([^<]+)<\/path>/g, ABS=/\/[\w.][\w.\/+-]*/g;
function pathsIn(d){const t=[...d.matchAll(TAG)].map(m=>(m[1]??'').trim()); return t.length?t:(d.match(ABS)??[]);}
function resolve(d){ if(d===undefined) return; let best;
 for(const c of pathsIn(d)){const b=c.slice(c.lastIndexOf('/')+1); for(const p of byBase.get(b)??[]){ if(c!==p&&!c.endsWith('/'+p))continue; if(best===undefined||p.length>best.length)best=p; }} return best; }
const lines=fs.readFileSync('fixtures/events/2026-09-19-nodegoat-2.jsonl','utf8').trim().split('\n').map(l=>JSON.parse(l));
let tools=0,withDetail=0,hits=0; const uniq=new Set(); const byLabel={}; const byDept={};
for(const e of lines){ if(e.kind!=='tool')continue; tools++; if(e.detail!==undefined)withDetail++; const r=resolve(e.detail); if(r===undefined)continue; hits++; uniq.add(r); byLabel[e.label]=(byLabel[e.label]||0)+1;
  const d=e.agentId.split('-').find(s=>['secrets','injection','access','data','dependencies','platform'].includes(s))??'(lead)'; byDept[d]=(byDept[d]||0)+1; }
console.log({events:lines.length,tools,withDetail,resolved:hits,uniqueFiles:uniq.size,inventory:safety.target.files.length});
console.log('by tool',byLabel); console.log('by department',byDept);
"

